def parse_query_string(qs: str) -> dict[str, str]:
    """Parse a URL query string into a dict (later values win on duplicate keys)."""
    result: dict[str, str] = {}
    if qs:
        qs = qs.lstrip('?')
        pairs = qs.split("&")
        for pair in pairs:
            if '=' in pair:
                k, v = pair.split("=", 1)
                result[k] = v
            else:
                result[pair] = ''
    return result

