import operator

_OPS = {"+": operator.add, "-": operator.sub, "*": operator.mul, "/": operator.truediv}


def rpn_eval(tokens):
    """Evaluate a list of RPN tokens and return a float."""
    if not tokens:
        raise ValueError('empty expression')
    stack = []
    for tok in tokens:
        if tok in _OPS:
            if len(stack) < 2:
                raise ValueError('insufficient operands')
            b = stack.pop()
            a = stack.pop()
            stack.append(_OPS[tok](a, b))
        else:
            try:
                stack.append(float(tok))
            except ValueError:
                raise ValueError(f'unknown token: {tok}')
    if len(stack) != 1:
        raise ValueError('expression leaves more than one value')
    return stack[0]

