def parse_csv_line(line: str) -> list[str]:
    """Parse one CSV line into a list of fields."""
    fields = []
    current_field = ""
    in_quotes = False
    for char in line:
        if char == '"' and not in_quotes:
            in_quotes = True
        elif char == '"' and in_quotes:
            in_quotes = False
        elif char == ',' and not in_quotes:
            fields.append(current_field)
            current_field = ""
        else:
            current_field += char
    fields.append(current_field)
    if len(fields) == 0:
        return [""]
    return fields

